116	    # Wait
117	    Start-Sleep -Seconds $Duration
118	    
119	    # Stop recording
120	    Write-Host "Stopping measurement..." -ForegroundColor Cyan
121	    Start-Process $xperfPath -ArgumentList "-d", $etlFile, "-stop" -Wait -WindowStyle Hidden -ErrorAction Stop | Out-Null
122	    
123	    # Convert to text
124	    Write-Host "Converting data..." -ForegroundColor Cyan
125	    Start-Process $xperfPath -ArgumentList "-i", $etlFile, "-a", "dpcisr" -RedirectStandardOutput $txtFile -Wait -WindowStyle Hidden -ErrorAction Stop | Out-Null
126	    
127	    # Analyze output
128	    $content = Get-Content $txtFile -Raw
129	    
130	    # Extract total time
131	    $intervalTime = 0
132	    if ($content -match "CPU Usage from \d+ us to (\d+) us") {
133	        $intervalTime = [double]$matches[1]
134	    }
135	    
136	    # Extract DPC data
137	    $dpcData = @{}
138	    if ($content -match "(?s)DPC Info.*?Module(.*?)Total = \d+") {
139	        $table = $matches[1].Trim()
140	        foreach ($line in $table -split "`r?`n") {
141	            if ($line -match "(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*([^,]+)$") {
142	                $total = 0
143	                for ($i = 1; $i -le 8; $i++) {
144	                    $val = $matches[$i].Trim().Split(' ')[0]
145	                    if ([double]::TryParse($val, [ref]$null)) {
146	                        $total += [double]$val
147	                    }
148	                }
149	                $module = $matches[9].Trim()
150	                $dpcData[$module] = $total
151	            }
152	        }
153	    }
154	    
155	    # Extract ISR data
156	    $isrData = @{}
157	    if ($content -match "(?s)Interrupt Info.*?Module(.*?)Total = \d+") {
158	        $table = $matches[1].Trim()
159	        foreach ($line in $table -split "`r?`n") {
160	            if ($line -match "(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*(\d+.*?)\s*,\s*([^,]+)$") {
161	                $total = 0
162	                for ($i = 1; $i -le 8; $i++) {
163	                    $val = $matches[$i].Trim().Split(' ')[0]
164	                    if ([double]::TryParse($val, [ref]$null)) {
165	                        $total += [double]$val
166	                    }
167	                }
168	                $module = $matches[9].Trim()
169	                $isrData[$module] = $total
170	            }
171	        }
172	    }
173	    
174	    # Calculate impact
175	    $dpcTotal = ($dpcData.Values | Measure-Object -Sum).Sum
176	    $isrTotal = ($isrData.Values | Measure-Object -Sum).Sum
177	    
178	    $dpcImpact = if ($intervalTime -gt 0) { [Math]::Round(($dpcTotal / $intervalTime) * 100, 3) } else { 0 }
179	    $isrImpact = if ($intervalTime -gt 0) { [Math]::Round(($isrTotal / $intervalTime) * 100, 3) } else { 0 }
180	    $totalImpact = $dpcImpact + $isrImpact
181	    
182	    # Generate report
183	    $report = @()
184	    $report += "----- Total DPC -----"
185	    foreach ($key in $dpcData.Keys) {
186	        $report += "$key -> $($dpcData[$key])"
187	    }
188	    $report += ""
189	    $report += "----- Total ISR -----"
190	    foreach ($key in $isrData.Keys) {
191	        $report += "$key -> $($isrData[$key])"
192	    }
193	    $report += ""
194	    $report += "----- DPC/ISR Effective Impact (%) -----"
195	    $report += "DPC Impact (%): $dpcImpact"
196	    $report += "ISR Impact (%): $isrImpact"
197	    $report += "Total Impact (%): $totalImpact"
198	    $report += ""
199	    $report += "----- Data -----"
200	    $report += "Total Interval Time (us): $intervalTime"
201	    $report += "Total DPC Time: $dpcTotal"
202	    $report += "Total ISR Time: $isrTotal"
203	    $report += "Module DPC Count: $($dpcData.Count)"
204	    $report += "Module ISR Count: $($isrData.Count)"
205	    
206	    # Replace umlauts
207	    $report = $report | ForEach-Object { Replace-Umlauts $_ }
208	    
209	    # Save output
210	    $report | Out-File $outputFile -Encoding UTF8
211	    Write-Host "`nResults saved in: $outputFile`n" -ForegroundColor Green
212	    
213	    # Prepare data for GUI
214	    $resultData = @{
215	        isr_total    = $isrTotal
216	        dpc_total    = $dpcTotal
217	        intervalTime = $intervalTime
218	        dpcImpact    = $dpcImpact
219	        isrImpact    = $isrImpact
220	        totalImpact  = $totalImpact
221	        isrDrivers   = @($isrData.GetEnumerator() | ForEach-Object { [PSCustomObject]@{Module = $_.Key; Value = $_.Value} })
222	        dpcDrivers   = @($dpcData.GetEnumerator() | ForEach-Object { [PSCustomObject]@{Module = $_.Key; Value = $_.Value} })
223	        fullReport   = $report -join "`r`n"
224	    }
225	    
226	    # Save data for GUI
227	    $resultData | ConvertTo-Json | Out-File $jsonFile -Encoding UTF8
228	    
229	    # Start GUI (calling the new, corrected script name)
230	    Write-Host "Starting GUI to display results..." -ForegroundColor Cyan
231	    $guiScriptPath = Join-Path $PSScriptRoot "Show-DPCISR_GUI.ps1"
232	    $process = Start-Process PowerShell -ArgumentList "-NoProfile", "-ExecutionPolicy", "Bypass", "-NoExit", "-File", "`"$guiScriptPath`"", "`"$jsonFile`"" -PassThru
233	    $process.WaitForExit() # Use WaitForExit for better process control
234	    $guiStarted = $true
235	}
236	catch {
237	    Write-Host "Error: $($_.Exception.Message)" -ForegroundColor Red
238	}
